CREATE TABLE role_policies(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,role_name VARCHAR(60) NOT NULL,permissions TEXT NOT NULL,system_role BOOLEAN NOT NULL,updated_at TIMESTAMP(6) NOT NULL,UNIQUE KEY uk_role_tenant_name(tenant_id,role_name));
CREATE TABLE administrators(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,auth_user_id BINARY(16),name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(32),role_name VARCHAR(60) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,UNIQUE KEY uk_admin_tenant_email(tenant_id,email));
CREATE TABLE admin_api_keys(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,key_id VARCHAR(40) NOT NULL UNIQUE,secret_hash VARCHAR(64) NOT NULL,name VARCHAR(120) NOT NULL,role_name VARCHAR(60) NOT NULL,scopes VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,last_used_at TIMESTAMP(6),INDEX idx_api_key_tenant(tenant_id));
CREATE TABLE platform_settings(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,setting_key VARCHAR(80) NOT NULL,setting_value TEXT,updated_at TIMESTAMP(6) NOT NULL,UNIQUE KEY uk_setting_tenant_key(tenant_id,setting_key));
